using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Windows.Forms;

// One shared layout drives rendering, scroll offsets and copy hit testing.
public class SelectableNoteLabel:MixedLabel {
    protected sealed class Cell {public int Index,EndIndex;public bool IsBreak,Bold,Highlight;public RectangleF Bounds;}
    readonly List<Cell> cells=new List<Cell>();bool layoutDirty=true,selecting;int anchor,caret,wheelRemainder;float lineHeight,scrollOffset,maxScroll;
    List<NoteFormat> formats=new List<NoteFormat>();readonly WheelRouter wheelRouter;
    protected virtual RectangleF TextBounds {get{return new RectangleF(16,74,Math.Max(1,Width-32),Math.Max(1,Height-100));}}
    public float ScrollOffset {get{return scrollOffset;}}
    public List<NoteFormat> Formats {get{return NoteFormatting.Copy(formats);}set{formats=NoteFormatting.Copy(value);layoutDirty=true;Invalidate();}}
    public bool HasTextSelection {get{return anchor!=caret;}}
    public string SelectedText {get{int first=Math.Min(anchor,caret),last=Math.Max(anchor,caret);return Text.Substring(Math.Min(first,Text.Length),Math.Max(0,Math.Min(last,Text.Length)-Math.Min(first,Text.Length)));}}
    public SelectableNoteLabel(){SetStyle(ControlStyles.Selectable,true);TabStop=true;AccessibleRole=AccessibleRole.Text;wheelRouter=new WheelRouter(this);Application.AddMessageFilter(wheelRouter);}
    protected override void Dispose(bool disposing){if(disposing)Application.RemoveMessageFilter(wheelRouter);base.Dispose(disposing);}
    sealed class WheelRouter:IMessageFilter {readonly SelectableNoteLabel owner;public WheelRouter(SelectableNoteLabel value){owner=value;}public bool PreFilterMessage(ref Message m){if(m.Msg!=0x020a||owner.IsDisposed||!owner.Visible||!owner.IsHandleCreated)return false;long location=m.LParam.ToInt64();Point p=new Point((short)(location&0xffff),(short)((location>>16)&0xffff));if(!owner.TextBounds.Contains(owner.PointToClient(p)))return false;Form top=Form.ActiveForm;if(top!=null&&top!=owner.FindForm())return false;owner.ScrollWheel((short)((m.WParam.ToInt64()>>16)&0xffff));return true;}}
    public void ClearTextSelection(){anchor=caret=0;selecting=false;Invalidate();}
    public void ResetView(){ClearTextSelection();scrollOffset=0;layoutDirty=true;Invalidate();}
    public void SelectAllText(){Focus();anchor=0;caret=Text.Length;Invalidate();}
    protected override void OnTextChanged(EventArgs e){layoutDirty=true;anchor=caret=0;scrollOffset=0;formats.Clear();base.OnTextChanged(e);}
    protected override void OnFontChanged(EventArgs e){layoutDirty=true;base.OnFontChanged(e);}
    protected override void OnSizeChanged(EventArgs e){layoutDirty=true;base.OnSizeChanged(e);}
    protected void EnsureLayout(Graphics g){if(!layoutDirty)return;cells.Clear();RectangleF body=TextBounds;float x=body.Left,y=body.Top,pixels=Font.Unit==GraphicsUnit.Pixel?Font.Size:Font.SizeInPoints*96/72;
        using(Font cn=Typography.Chinese(pixels,FontStyle.Regular))using(Font en=Typography.Latin(pixels,FontStyle.Regular))using(Font cb=Typography.Chinese(pixels,FontStyle.Bold))using(Font eb=Typography.Latin(pixels,FontStyle.Bold))using(StringFormat measure=(StringFormat)StringFormat.GenericTypographic.Clone()){
            measure.FormatFlags|=StringFormatFlags.MeasureTrailingSpaces;lineHeight=Math.Max(Math.Max(cn.GetHeight(g),en.GetHeight(g)),Math.Max(cb.GetHeight(g),eb.GetHeight(g)))*Typography.NoteLineSpacing;int run=0;
            for(int i=0;i<Text.Length;i++){while(run<formats.Count&&formats[run].Start+formats[run].Length<=i)run++;NoteFormat style=run<formats.Count&&formats[run].Start<=i?formats[run]:null;bool bold=style!=null&&style.Bold,highlight=style!=null&&style.Highlight;char c=Text[i];if(c=='\r')continue;if(c=='\n'){cells.Add(new Cell{Index=i>0&&Text[i-1]=='\r'?i-1:i,EndIndex=i+1,IsBreak=true,Bounds=new RectangleF(x,y,6,lineHeight)});x=body.Left;y+=lineHeight;continue;}Font f=Typography.ChineseCharacter(c)?(bold?cb:cn):(bold?eb:en);float width=g.MeasureString(c.ToString(),f,10000,measure).Width;if(x>body.Left&&x-body.Left+width>body.Width){x=body.Left;y+=lineHeight;}cells.Add(new Cell{Index=i,EndIndex=i+1,Bold=bold,Highlight=highlight,Bounds=new RectangleF(x,y,width,lineHeight)});x+=width;}
        }maxScroll=Math.Max(0,y+lineHeight-body.Bottom);scrollOffset=Math.Min(scrollOffset,maxScroll);layoutDirty=false;
    }
    public void ScrollWheel(int delta){using(Graphics g=CreateGraphics())EnsureLayout(g);wheelRemainder+=delta;int ticks=wheelRemainder/120;wheelRemainder%=120;if(ticks==0)return;int lines=SystemInformation.MouseWheelScrollLines;float step=lines<0?TextBounds.Height:lineHeight*Math.Max(1,lines);scrollOffset=Math.Max(0,Math.Min(maxScroll,scrollOffset-ticks*step));Invalidate();}
    protected override void OnMouseWheel(MouseEventArgs e){ScrollWheel(e.Delta);base.OnMouseWheel(e);}
    protected int HitIndex(Point point){using(Graphics g=CreateGraphics())EnsureLayout(g);if(cells.Count==0)return 0;RectangleF body=TextBounds;int row=Math.Max(0,(int)Math.Floor((point.Y+scrollOffset-body.Top)/lineHeight));Cell last=null;foreach(Cell cell in cells){int cellRow=(int)Math.Round((cell.Bounds.Top-body.Top)/lineHeight);if(cellRow<row){last=cell;continue;}if(cellRow>row)return last==null?cell.Index:last.EndIndex;if(cell.IsBreak)return cell.Index;if(point.X<cell.Bounds.Left+cell.Bounds.Width/2)return cell.Index;last=cell;}return last==null?0:Math.Min(Text.Length,last.EndIndex);}
    protected void PaintNoteContent(Graphics g){EnsureLayout(g);int first=Math.Min(anchor,caret),last=Math.Max(anchor,caret);GraphicsState saved=g.Save();try{g.SetClip(TextBounds,CombineMode.Intersect);float pixels=Font.Unit==GraphicsUnit.Pixel?Font.Size:Font.SizeInPoints*96/72;using(Font cn=Typography.Chinese(pixels,FontStyle.Regular))using(Font en=Typography.Latin(pixels,FontStyle.Regular))using(Font cb=Typography.Chinese(pixels,FontStyle.Bold))using(Font eb=Typography.Latin(pixels,FontStyle.Bold))using(StringFormat measure=(StringFormat)StringFormat.GenericTypographic.Clone())using(Brush ink=new SolidBrush(ForeColor))using(Brush darkInk=new SolidBrush(Color.FromArgb(64,57,26)))using(Brush highlight=new SolidBrush(NoteFormatting.Yellow))using(Brush selection=new SolidBrush(Color.FromArgb(145,193,242))){foreach(Cell cell in cells){RectangleF bounds=cell.Bounds;bounds.Y-=scrollOffset;if(bounds.Bottom<=TextBounds.Top||bounds.Top>=TextBounds.Bottom)continue;if(cell.Highlight)g.FillRectangle(highlight,bounds);if(HasTextSelection&&cell.Index>=first&&cell.Index<last)g.FillRectangle(selection,bounds);if(!cell.IsBreak){char c=Text[cell.Index];Font f=Typography.ChineseCharacter(c)?(cell.Bold?cb:cn):(cell.Bold?eb:en);Font chinese=cell.Bold?cb:cn,latin=cell.Bold?eb:en;float ascent=f.FontFamily.GetCellAscent(f.Style)*f.Size/f.FontFamily.GetEmHeight(f.Style),baseline=Math.Max(chinese.FontFamily.GetCellAscent(chinese.Style)*chinese.Size/chinese.FontFamily.GetEmHeight(chinese.Style),latin.FontFamily.GetCellAscent(latin.Style)*latin.Size/latin.FontFamily.GetEmHeight(latin.Style));g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;g.DrawString(c.ToString(),f,cell.Highlight?darkInk:ink,bounds.Left,bounds.Top+baseline-ascent,measure);}}}}finally{g.Restore(saved);}if(maxScroll>0){float height=Math.Max(18,TextBounds.Height*TextBounds.Height/(TextBounds.Height+maxScroll)),top=TextBounds.Top+(TextBounds.Height-height)*scrollOffset/maxScroll;using(Brush thumb=new SolidBrush(BlueTheme.Muted))g.FillRectangle(thumb,Width-7,top,2,height);}}
    protected override void OnMouseDown(MouseEventArgs e){if(e.Button==MouseButtons.Left&&e.Clicks==1&&TextBounds.Contains(e.Location)){Focus();int index=HitIndex(e.Location);if((ModifierKeys&Keys.Shift)==0)anchor=index;caret=index;selecting=true;Capture=true;Invalidate();}base.OnMouseDown(e);}
    protected override void OnMouseMove(MouseEventArgs e){if(selecting){if(e.Y<TextBounds.Top)scrollOffset=Math.Max(0,scrollOffset-lineHeight);else if(e.Y>TextBounds.Bottom)scrollOffset=Math.Min(maxScroll,scrollOffset+lineHeight);caret=HitIndex(e.Location);Invalidate();}base.OnMouseMove(e);}
    protected override void OnMouseUp(MouseEventArgs e){if(e.Button==MouseButtons.Left&&selecting){caret=HitIndex(e.Location);selecting=false;Capture=false;Invalidate();}base.OnMouseUp(e);}
    protected override void OnMouseCaptureChanged(EventArgs e){if(!Capture)selecting=false;base.OnMouseCaptureChanged(e);}
    protected override void OnKeyDown(KeyEventArgs e){if((e.Control&&e.KeyCode==Keys.C)||(e.Control&&e.KeyCode==Keys.Insert)){CopySelection();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.A){SelectAllText();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.Escape){ClearTextSelection();e.SuppressKeyPress=true;}base.OnKeyDown(e);}
    protected virtual void PublishCopy(string text){Clipboard.SetText(text,TextDataFormat.UnicodeText);}
    public bool CopySelection(){if(!HasTextSelection)return false;try{PublishCopy(SelectedText);return true;}catch(System.Runtime.InteropServices.ExternalException){MessageBox.Show("剪贴板暂不可用，请稍后重试。","进步签");return false;}}
    protected Point TestPoint(int index,bool after){using(Graphics g=CreateGraphics())EnsureLayout(g);foreach(Cell cell in cells)if(cell.Index==index)return new Point((int)Math.Ceiling(after?cell.Bounds.Right:cell.Bounds.Left),(int)(cell.Bounds.Top-scrollOffset+lineHeight/2));throw new ArgumentOutOfRangeException("index");}
}
public static class SelectableNoteTests {
    sealed class Probe:PaperRecordLabel {public string Copied;protected override void PublishCopy(string text){Copied=text;}public void Drag(int first,int last){Point a=TestPoint(first,false),b=TestPoint(last,true);OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,a.X,a.Y,0));OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,b.X,b.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,b.X,b.Y,0));}public void Key(Keys key){OnKeyDown(new KeyEventArgs(key));}}
    static void Check(bool ok,string reason){if(!ok)throw new Exception(reason);}
    public static void Run(string directory){Directory.CreateDirectory(directory);using(Form form=new Form{ClientSize=new Size(344,520)})using(Probe note=new Probe{Dock=DockStyle.Fill,Font=Typography.Chinese(17,FontStyle.Regular),ForeColor=BlueTheme.Ink,Text="第一行 ABC\r\n第二行，尾巴"}){
        form.Controls.Add(note);form.Show();Application.DoEvents();string original=note.Text;note.Drag(0,6);Check(note.SelectedText=="第一行 ABC","Mixed-font hit testing incorrect");note.Key(Keys.Control|Keys.C);Check(note.Copied=="第一行 ABC"&&note.Text==original,"Copy mutated text");
        using(Bitmap image=new Bitmap(note.Width,note.Height)){note.DrawToBitmap(image,note.ClientRectangle);image.Save(Path.Combine(directory,"选中复制预览.png"),System.Drawing.Imaging.ImageFormat.Png);}
        note.Key(Keys.Control|Keys.A);Check(note.SelectedText==original,"Select all lost line breaks");note.CopySelection();Check(note.Copied==original,"Context copy lost text");note.Key(Keys.Escape);Check(!note.HasTextSelection&&!note.CopySelection(),"Clearing selection failed");note.Drag(4,11);Check(note.SelectedText==original.Substring(4,8),"Cross-line selection lost CRLF");note.SelectAllText();note.CategoryName="工作";Check(!note.HasTextSelection,"Selection leaked to a different category");note.SelectAllText();note.Text="另一条记录";Check(!note.HasTextSelection,"Selection leaked after text changed");
        note.Width=145;note.Text="长一些的正文 ABC 123 用于检查自动换行位置";form.Controls.Remove(note);note.Dock=DockStyle.None;note.Size=new Size(145,520);form.Controls.Add(note);note.Drag(0,note.Text.Length-1);Check(note.SelectedText==note.Text,"Wrapped selection lost text");form.Close();
    }File.WriteAllText(Path.Combine(directory,"selection-test-result.txt"),"PASS: drag selection, mixed fonts, CRLF across lines, wrapped text, Ctrl+C/Ctrl+A/Escape, copy without editing, and selection reset on category/text changes. Clipboard output was intercepted; real clipboard was not overwritten.");}
}
